# txt2tags - source document parsing and configuration management
# Port of txt2tags3_mod/config.py to Perl 5

use strict;
use warnings;
use Exporter 'import';

our $VERSION = '3.9.0';

use Text::Txt2tags::Constants qw(
    $MY_NAME %FLAGS %OPTIONS %ACTIONS %MACROS %SETTINGS
    @NO_TARGET @NO_MULTI_INPUT @CONFIG_KEYWORDS @TARGETS
    $STDIN $STDOUT $MODULEIN $MODULEOUT
    DFT_TEXT_WIDTH DFT_SLIDE_WIDTH DFT_SLIDE_HEIGHT
    DFT_SLIDE_WEB_WIDTH DFT_SLIDE_WEB_HEIGHT
    DFT_SLIDE_PRINT_WIDTH DFT_SLIDE_PRINT_HEIGHT
);
use File::Basename ();
use File::Spec     ();
use Text::Txt2tags::Utils   qw(Error Debug Message Readfile dotted_spaces);
use Text::Txt2tags::Regexes qw(getRegexes);
use Text::Txt2tags::State   qw($VERBOSE $QUIET $DEBUG @RC_RAW @CMDLINE_RAW);

# Aliases for use in sub-packages below (they can't inherit imports)
our (%FLAGS, %OPTIONS, %ACTIONS, %SETTINGS, @CONFIG_KEYWORDS, @TARGETS, @NO_TARGET);
our ($MY_NAME, $STDIN, $STDOUT, $MODULEIN, $MODULEOUT);
BEGIN {
    *FLAGS             = \%Text::Txt2tags::Constants::FLAGS;
    *OPTIONS           = \%Text::Txt2tags::Constants::OPTIONS;
    *ACTIONS           = \%Text::Txt2tags::Constants::ACTIONS;
    *SETTINGS          = \%Text::Txt2tags::Constants::SETTINGS;
    *CONFIG_KEYWORDS   = \@Text::Txt2tags::Constants::CONFIG_KEYWORDS;
    *TARGETS           = \@Text::Txt2tags::Constants::TARGETS;
    *NO_TARGET         = \@Text::Txt2tags::Constants::NO_TARGET;
    *MY_NAME           = \$Text::Txt2tags::Constants::MY_NAME;
    *STDIN             = \$Text::Txt2tags::Constants::STDIN;
    *STDOUT            = \$Text::Txt2tags::Constants::STDOUT;
    *MODULEIN          = \$Text::Txt2tags::Constants::MODULEIN;
    *MODULEOUT         = \$Text::Txt2tags::Constants::MODULEOUT;
}

# ---------------------------------------------------------------------------
# SourceDocument
# ---------------------------------------------------------------------------

package Text::Txt2tags::SourceDocument;
# Utility function aliases for this sub-package
sub Error     { Text::Txt2tags::Utils::Error(@_)     }
sub Debug     { Text::Txt2tags::Utils::Debug(@_)     }
sub Message   { Text::Txt2tags::Utils::Message(@_)   }
sub Readfile  { Text::Txt2tags::Utils::Readfile(@_)  }
sub getRegexes{ Text::Txt2tags::Regexes::getRegexes(@_) }

sub new {
    my ($class, %args) = @_;
    my $self = bless {
        areas      => [qw(head conf body)],
        arearef    => [],
        areas_fancy=> '',
        filename   => $args{filename} // '',
        buffer     => [],
    }, $class;

    if ($args{filename}) {
        $self->scan_file($args{filename});
    }
    elsif ($args{contents}) {
        $self->scan($args{contents});
    }
    return $self;
}

sub split_doc {
    my ($self) = @_;
    return ($self->get('head'), $self->get('conf'), $self->get('body'));
}

sub get {
    my ($self, $areaname) = @_;
    my @areas = @{ $self->{areas} };
    # Head area always returns 3 lines (title/author/date), even if empty
    if ($areaname eq 'head') {
        return ['', '', ''] unless @{ $self->{buffer} };
    }
    else {
        return [] unless grep { $_ eq $areaname } @areas;
        return [] unless @{ $self->{buffer} };
    }

    my $buf    = $self->{buffer};
    my $bufini = 1;
    my $bufend = $#$buf;

    my ($ini, $end);
    my ($ref0, $ref1, $ref2) = @{ $self->{arearef} };

    if ($areaname eq 'head') {
        $ini = $bufini;
        $end = ($ref1 || $ref2 || $bufend + 1) - 1;
    }
    elsif ($areaname eq 'conf') {
        $ini = $ref1;
        $end = ($ref2 || $bufend + 1) - 1;
    }
    elsif ($areaname eq 'body') {
        $ini = $ref2;
        $end = $bufend;
    }
    else {
        Text::Txt2tags::Utils::Error("Unknown area name '$areaname'");
    }

    my @lines = @{$buf}[$ini .. $end];

    # Head always has exactly 3 lines
    if ($areaname eq 'head') {
        push @lines, '' while @lines < 3;
    }
    return \@lines;
}

sub scan_file {
    my ($self, $filename) = @_;
    Debug("source file: $filename");
    Message('Loading source document', 1);
    my $buf = Readfile($filename, 1);   # remove_linebreaks=1
    $self->scan($buf);
}

sub scan {
    my ($self, $lines) = @_;
    my @buf = @$lines;

    Text::Txt2tags::Utils::Error("The input file is empty: $self->{filename}")
        if !@buf;

    my $cfg_parser = Text::Txt2tags::ConfigLines->new;
    unshift @buf, '';   # text starts at pos 1

    my @ref = (1, 4, 0);
    # No header if: first line is blank OR starts with '%' (config/comment directive)
    if (!$buf[1] || $buf[1] !~ /\S/ || $buf[1] =~ /^%/) {
        $ref[0] = 0;
        $ref[1] = ($buf[1] && $buf[1] =~ /^%/) ? 1 : 2;  # conf at line 1 for %-lines
    }

    my $rgx = getRegexes();
    my $on_comment_block = 0;

    for my $i ($ref[1] .. $#buf) {
        my $line = $buf[$i] // '';
        # Handle comment blocks
        if (!$on_comment_block && $line =~ $rgx->{blockCommentOpen}) {
            $on_comment_block = 1;
            next;
        }
        if ($on_comment_block && $line =~ $rgx->{blockCommentOpen}) {
            $on_comment_block = 0;
            next;
        }
        next if $on_comment_block;

        if ($line =~ /\S/) {
            my $is_comment = substr($line, 0, 1) eq '%';
            my $is_macro   = $line =~ $rgx->{macros};
            my $is_toc     = $line =~ $rgx->{toc};
            my $is_include = ($cfg_parser->parse_line($line, 'include'))[1];
            my $is_csv     = ($cfg_parser->parse_line($line, 'csv'))[1];

            unless ($is_comment && !$is_macro && !$is_toc
                                && !$is_include && !$is_csv) {
                $ref[2] = $i;
                last;
            }
        }
    }

    $ref[1] = 0 if $ref[1] == $ref[2];   # no conf area

    for my $i (0, 1, 2) {
        if ($ref[$i] >= scalar @buf) { $ref[$i] = 0 }
        if (!$ref[$i]) { $self->{areas}[$i] = '' }
    }

    Debug(sprintf('Head,Conf,Body start line: %s %s %s', @ref));
    $self->{arearef} = \@ref;
    $self->{buffer}  = \@buf;
    $self->{areas_fancy} = join(' ', grep { $_ } @{ $self->{areas} })
        . ' (' . join(' ', map { $_ // '' } @ref) . ')';
    Message("Areas found: $self->{areas_fancy}", 2);
}

sub get_raw_config {
    my ($self) = @_;
    return [] unless grep { $_ eq 'conf' } @{ $self->{areas} };
    Message('Scanning source document CONF area', 1);
    my $raw = Text::Txt2tags::ConfigLines->new(
        file_     => $self->{filename},
        lines     => $self->get('conf'),
        first_line=> $self->{arearef}[1],
    )->get_raw_config;
    Debug("document raw config: " . join(', ', map { "[@$_]" } @$raw), 1);
    return $raw;
}

# ---------------------------------------------------------------------------
# ConfigLines – parse %! config lines
# ---------------------------------------------------------------------------

package Text::Txt2tags::ConfigLines;
sub Debug   { Text::Txt2tags::Utils::Debug(@_)   }
sub Error   { Text::Txt2tags::Utils::Error(@_)   }
sub Message { Text::Txt2tags::Utils::Message(@_) }

sub new {
    my ($class, %args) = @_;
    return bless {
        file_      => $args{file_}      // '',
        lines      => $args{lines}      // [],
        first_line => $args{first_line} // 1,
    }, $class;
}

# Returns (target, value) or ('', '') if not a config line for $keyword
sub parse_line {
    my ($self, $line, $keyword) = @_;
    $keyword //= '';

    # %!keyword[target]: value
    if ($line =~ /^%!\s*(\w[\w-]*)\s*(?:\(([^)]*)\))?\s*:\s*(.*)$/i) {
        my ($key, $target, $val) = ($1, $2 // 'all', $3);
        $key    = lc $key;
        $target = lc($target || 'all');
        $val    =~ s/\s+$//;
        if (!$keyword || $key eq lc($keyword)) {
            return ($target, $val, $key);
        }
    }
    return ('', '', '');
}

sub get_raw_config {
    my ($self, $depth) = @_;
    $depth //= 0;
    my @raw;
    my $n = $self->{first_line};
    for my $line (@{ $self->{lines} }) {
        $line //= '';
        chomp $line;
        if ($line =~ /^%!/) {
            my ($target, $val, $key) = $self->parse_line($line);
            if ($key eq 'includeconf' && $depth < 5) {
                # Resolve path relative to the current file
                my $dir = '';
                if ($self->{file_}) {
                    $dir = File::Basename::dirname($self->{file_});
                }
                my $inc = ($dir && $dir ne '.')
                    ? File::Spec->catfile($dir, $val)
                    : $val;
                if (-r $inc) {
                    open my $fh, '<', $inc or next;
                    my @inc_lines = <$fh>;
                    close $fh;
                    chomp @inc_lines;
                    my $sub = Text::Txt2tags::ConfigLines->new(
                        file_      => $inc,
                        lines      => \@inc_lines,
                        first_line => 1,
                    );
                    push @raw, @{ $sub->get_raw_config($depth + 1) };
                }
                else {
                    Debug("includeconf: cannot read '$inc'", 1);
                }
            }
            elsif ($key) {
                push @raw, [$target, $key, $val];
                Debug("config: target=$target key=$key val=$val", 1);
            }
        }
        $n++;
    }
    return \@raw;
}

# ---------------------------------------------------------------------------
# ConfigMaster – parse, validate and merge config
# ---------------------------------------------------------------------------

package Text::Txt2tags::ConfigMaster;
sub Debug   { Text::Txt2tags::Utils::Debug(@_)   }
sub Error   { Text::Txt2tags::Utils::Error(@_)   }
sub Message { Text::Txt2tags::Utils::Message(@_) }

sub new {
    my ($class, $raw, $target) = @_;
    $raw    //= [];
    $target //= '';
    my $self = bless {
        raw         => $raw,
        target      => $target,
        parsed      => {},
        dft_options => { %OPTIONS },
        dft_flags   => { %FLAGS   },
        dft_actions => { %ACTIONS },
        dft_settings=> { %SETTINGS},
        incremental => [qw(verbose)],
        numeric     => [qw(toc-level split width height)],
        multi       => [qw(infile preproc postproc postvoodoo options style stylepath)],
    }, $class;
    $self->{defaults} = $self->_get_defaults;
    $self->{off}      = $self->_get_off;
    return $self;
}

sub _get_defaults {
    my ($self) = @_;
    my %empty;
    $empty{$_} = '' for @CONFIG_KEYWORDS;
    %empty = (%empty, %{ $self->{dft_options} }, %{ $self->{dft_flags} },
              %{ $self->{dft_actions} }, %{ $self->{dft_settings} });
    $empty{realcmdline}       = '';
    $empty{sourcefile}        = '';
    $empty{currentsourcefile} = '';
    return \%empty;
}

sub _get_off {
    my ($self) = @_;
    my %off;
    for my $key (keys %{ $self->{defaults} }) {
        my $val = $self->{defaults}{$key};
        if (!defined $val) {
            $off{$key} = '';
        }
        elsif ($val =~ /^\d+$/) {
            $off{$key} = 0;
        }
        elsif (ref $val eq 'ARRAY') {
            $off{$key} = [];
        }
        else {
            $off{$key} = '';
        }
    }
    return \%off;
}

sub _check_target {
    my ($self) = @_;
    $self->{target} ||= $self->find_value('target');
}

sub find_value {
    my ($self, $key) = @_;
    for my $entry (reverse @{ $self->{raw} }) {
        return $entry->[2] if $entry->[1] eq $key;
    }
    return '';
}

sub get_target_raw {
    my ($self) = @_;
    $self->_check_target;
    my @ret;
    for my $entry (@{ $self->{raw} }) {
        push @ret, $entry
            if $entry->[0] eq $self->{target} || $entry->[0] eq 'all';
    }
    return \@ret;
}

# Parse a preproc/postproc value string "'pattern' 'replacement'" into
# an arrayref [$pattern, $replacement].  Tokens may be single-quoted or
# unquoted (splitting on whitespace).
sub _parse_prepost_value {
    my ($val) = @_;
    my @tokens;
    # Match up to 2 tokens: "double quoted", 'single quoted', or unquoted-word
    # Mirrors Python's _parse_prepost regex.
    while (length $val && @tokens < 2) {
        $val =~ s/^\s+//;
        if ($val =~ s/^"([^"]*)"?//) {
            push @tokens, $1;
        }
        elsif ($val =~ s/^'([^']*)'?//) {
            push @tokens, $1;
        }
        elsif (@tokens == 1) {
            # Last token: take everything remaining (like Python's `(.*)`)
            $val =~ s/\s+$//;
            push @tokens, $val;
            last;
        }
        elsif ($val =~ s/^(\S+)//) {
            push @tokens, $1;
        }
        else {
            last;
        }
    }
    return [ $tokens[0] // '', $tokens[1] // '' ];
}

sub add {
    my ($self, $key, $val) = @_;
    $val //= '';

    # no- prefix = turn OFF
    if ($key =~ s/^no-//) {
        $val = $self->{off}{$key} // 0;
    }

    return unless exists $self->{defaults}{$key};

    # If value == default, remove
    if (defined $self->{defaults}{$key} && $val eq $self->{defaults}{$key}) {
        delete $self->{parsed}{$key};
        return;
    }

    # Flags/actions come empty → set to 1
    if ($val eq '' && (exists $self->{dft_flags}{$key}
                    || exists $self->{dft_actions}{$key})) {
        $val = 1;
    }

    # Multi-value
    if (grep { $_ eq $key } @{ $self->{multi} }) {
        $self->{parsed}{$key} //= [];
        # preproc/postproc/postvoodoo: parse value into [pattern, replacement]
        if ($key eq 'preproc' || $key eq 'postproc' || $key eq 'postvoodoo') {
            push @{ $self->{parsed}{$key} }, _parse_prepost_value($val);
        }
        else {
            push @{ $self->{parsed}{$key} }, $val;
        }
    }
    # Incremental
    elsif (grep { $_ eq $key } @{ $self->{incremental} }) {
        $self->{parsed}{$key} = ($self->{parsed}{$key} // 0) + ($val || 1);
    }
    else {
        $self->{parsed}{$key} = $val;
    }

    my $fk = Text::Txt2tags::Utils::dotted_spaces(sprintf('%12s', $key));
    Message("Added config $fk : $val", 3);
}

sub parse {
    my ($self) = @_;
    $self->_check_target;
    for my $entry (@{ $self->get_target_raw }) {
        my (undef, $key, $val) = @$entry;
        $self->add($key, $val);
    }
    return $self->{parsed};
}

sub get_outfile_name {
    my ($self, $config) = @_;
    my $infile  = $config->{sourcefile} // '';
    my $outfile = $config->{outfile}    // '';

    $outfile = $STDOUT   if $infile eq $STDIN    && !$outfile;
    $outfile = $MODULEOUT if $infile eq $MODULEIN && !$outfile;

    if (!$outfile && $infile && $config->{target}) {
        (my $base = $infile) =~ s/\.(txt|t2t)$//;
        my $tgt = $config->{target};
        $outfile = "$base.$tgt";
    }
    Debug(" infile: '$infile'",  1);
    Debug("outfile: '$outfile'", 1);
    return $outfile;
}

sub sanity {
    my ($self, $config, $gui) = @_;
    $gui //= 0;
    return {} unless $config && %$config;

    my $target = $config->{target} // '';

    unless ($target) {
        for my $action (@NO_TARGET) {
            if ($config->{$action}) { $target = 'txt'; last }
        }
    }

    unless ($gui) {
        unless ($target) {
            Text::Txt2tags::Utils::Error(
                "No target specified (try --help)\n\n"
              . "Please inform a target using the -t option or the %!target command.\n"
              . "Example: $MY_NAME -t html file.t2t\n\n"
              . "Run 'txt2tags --targets' to see all available targets."
            );
        }
        unless ($config->{infile}) {
            Text::Txt2tags::Utils::Error("Missing input file (try --help)");
        }
        unless (grep { $_ eq $target } @TARGETS) {
            Text::Txt2tags::Utils::Error(
                "Invalid target '$target'\n\n"
              . "Run 'txt2tags --targets' to see all available targets."
            );
        }
    }

    # Fill in defaults
    my %full = (%{ $self->{defaults} }, %$config);
    $config = \%full;

    # Numeric options
    for my $key (@{ $self->{numeric} }) {
        next unless exists $config->{$key} && defined $config->{$key};
        unless ($config->{$key} =~ /^\d+$/) {
            Text::Txt2tags::Utils::Error("--$key value must be a number");
        }
        $config->{$key} = int($config->{$key});
    }

    # Alias targets
    my %alias_map = (
        aap  => [qw(aat slides)],
        aas  => [qw(aat spread)],
        aatw => [qw(aat web)],
        aapw => [qw(aat slides web)],
        aasw => [qw(aat spread web)],
        aapp => [qw(aat slides print)],
    );
    if (exists $alias_map{$target}) {
        my ($real_tgt, @flags) = @{ $alias_map{$target} };
        $target = $real_tgt;
        $config->{$_} = 1 for @flags;
    }
    $config->{target} = $target;

    # Default width for ASCII Art
    if ($target eq 'aat') {
        $config->{width} ||= Text::Txt2tags::Constants::DFT_TEXT_WIDTH();
    }

    # Determine output file name if not already set
    $config->{outfile} ||= $self->get_outfile_name($config);

    return $config;
}

# ---------------------------------------------------------------------------
# Package exports
# ---------------------------------------------------------------------------
package Text::Txt2tags::Config;

our @EXPORT_OK = qw(SourceDocument ConfigMaster ConfigLines);

1;
__END__

=head1 NAME

Text::Txt2tags::Config - Document parsing and configuration management

=head1 DESCRIPTION

Port of C<txt2tags3_mod/config.py> to Perl 5.

Provides three classes:

=over 4

=item C<Text::Txt2tags::SourceDocument> – splits a .t2t file into head/conf/body.

=item C<Text::Txt2tags::ConfigLines> – parses C<%!> directive lines.

=item C<Text::Txt2tags::ConfigMaster> – merges and validates all config sources.

=back

=cut

END_OF_MODULE_SOURCE
    $_bundled{'Text/Txt2tags/Processing.pm'} = <<'END_OF_MODULE_SOURCE';
package Text::Txt2tags::Processing;

# txt2tags - MaskMaster, TitleMaster, TableMaster, BlockMaster, MacroMaster
# Port of txt2tags3_mod/processing.py to Perl 5

use strict;
use warnings;
use Exporter 'import';
use POSIX qw(strftime);

our $VERSION = '3.9.0';

use Text::Txt2tags::Constants qw(
    $ESCCHAR %MACROS $MY_NAME $MY_VERSION $MY_URL
);
use Text::Txt2tags::State qw(
    %CONF %TAGS %rules %regex $AUTOTOC $TARGET $DEBUG
);
use Text::Txt2tags::Utils  qw(Error Debug);
use Text::Txt2tags::Output qw(
    doEscape doFinalEscape doProtect enclose_me
    get_tagged_link fix_relative_path get_image_align
    maskEscapeChar unmaskEscapeChar compile_filters
    parse_deflist_term
);

# Package-level aliases so sub-packages can access these without qualification
our (%CONF, %TAGS, %rules, %regex, $AUTOTOC, $TARGET, %MACROS, $ESCCHAR);
BEGIN {
    *CONF    = \%Text::Txt2tags::State::CONF;
    *TAGS    = \%Text::Txt2tags::State::TAGS;
    *rules   = \%Text::Txt2tags::State::rules;
    *regex   = \%Text::Txt2tags::State::regex;
    *AUTOTOC = \$Text::Txt2tags::State::AUTOTOC;
    *TARGET  = \$Text::Txt2tags::State::TARGET;
    *MACROS  = \%Text::Txt2tags::Constants::MACROS;
    *ESCCHAR = \$Text::Txt2tags::Constants::ESCCHAR;
}

# ===========================================================================
# MacroMaster – expand %%macroname
# ===========================================================================

package Text::Txt2tags::MacroMaster;
use POSIX qw(strftime);
our (%CONF, %MACROS);
BEGIN {
    *CONF   = \%Text::Txt2tags::State::CONF;
    *MACROS = \%Text::Txt2tags::Constants::MACROS;
}

sub new {
    my ($class, %args) = @_;
    return bless { config => $args{config} // \%CONF }, $class;
}

sub expand {
    my ($self, $line) = @_;
    $line //= '';
    my $config = $self->{config};

    # %%macroname[(format)]
    $line =~ s{%%(?<name>[a-zA-Z]+)\b(?:\((?<fmt>[^)]*)\))?}{
        my $name = lc $+{name};
        my $fmt  = $+{fmt} // '';
        $self->_expand_macro($name, $fmt, $config);
    }ge;

    return $line;
}

sub _expand_macro {
    my ($self, $name, $fmt, $config) = @_;
    $config //= \%CONF;

    if ($name eq 'date') {
        my $f = $fmt || $MACROS{date} || '%Y-%m-%d';
        return strftime($f, localtime);
    }
    elsif ($name eq 'mtime') {
        my $f = $fmt || $MACROS{mtime} || '%Y%m%d';
        my $infile = $config->{currentsourcefile} // $config->{sourcefile} // $config->{infile} // '';
        my @t = ($infile && -f $infile) ? localtime((stat $infile)[9]) : localtime;
        return strftime($f, @t);
    }
    elsif ($name =~ /^(infile|currentfile|outfile)$/) {
        return $config->{$name} // '';
    }
    elsif ($name =~ /^header([123])$/) {
        return $config->{"header$1"} // '';
    }
    elsif ($name eq 'target') {
        return $config->{target} // '';
    }
    elsif ($name eq 'encoding') {
        return $config->{encoding} // '';
    }
    elsif ($name eq 'cmdline') {
        return join(' ', @{ $config->{realcmdline} // [] });
    }
    elsif ($name =~ /^(appurl|appname|appversion)$/) {
        return $config->{$name} // '';
    }
    elsif ($name eq 'cc') {
        return $config->{cc} // '';
    }
    else {
        return "%%$name";
    }
}

# ===========================================================================
# MaskMaster – protect inline structures during markup parsing
# ===========================================================================

package Text::Txt2tags::MaskMaster;
our (%regex, %TAGS, $TARGET, $AUTOTOC, $ESCCHAR);
BEGIN {
    *regex   = \%Text::Txt2tags::State::regex;
    *TAGS    = \%Text::Txt2tags::State::TAGS;
    *TARGET  = \$Text::Txt2tags::State::TARGET;
    *AUTOTOC = \$Text::Txt2tags::State::AUTOTOC;
    *ESCCHAR = \$Text::Txt2tags::Constants::ESCCHAR;
}
sub doEscape      { Text::Txt2tags::Output::doEscape(@_)      }
sub doFinalEscape { Text::Txt2tags::Output::doFinalEscape(@_) }
sub doProtect     { Text::Txt2tags::Output::doProtect(@_)     }
sub enclose_me    { Text::Txt2tags::Output::enclose_me(@_)    }
sub get_tagged_link    { Text::Txt2tags::Output::get_tagged_link(@_) }
sub fix_relative_path  { Text::Txt2tags::Output::fix_relative_path(@_) }
sub maskEscapeChar  { Text::Txt2tags::Output::maskEscapeChar(@_)  }
sub unmaskEscapeChar{ Text::Txt2tags::Output::unmaskEscapeChar(@_) }

sub new {
    my ($class) = @_;
    my $self = bless {
        linkmask    => 'vvvLINKNNNvvv',
        monomask    => 'vvvMONONNNvvv',
        macromask   => 'vvvMACRONNNvvv',
        rawmask     => 'vvvRAWNNNvvv',
        taggedmask  => 'vvvTAGGEDNNNvvv',
        mathmask    => 'vvvMATHNNNvvv',
        tocmask     => 'vvvTOCvvv',
        linkmaskre  => qr/vvvLINK(\d+)vvv/,
        monomaskre  => qr/vvvMONO(\d+)vvv/,
        macromaskre => qr/vvvMACRO(\d+)vvv/,
        rawmaskre   => qr/vvvRAW(\d+)vvv/,
        taggedmaskre=> qr/vvvTAGGED(\d+)vvv/,
        mathmaskre  => qr/vvvMATH(\d+)vvv/,
        macroman    => Text::Txt2tags::MacroMaster->new,
    }, $class;
    $self->reset;
    return $self;
}

sub reset {
    my ($self) = @_;
    $self->{linkbank}      = [];
    $self->{monobank}      = [];
    $self->{monobank_orig} = [];
    $self->{macrobank}     = [];
    $self->{rawbank}       = [];
    $self->{rawbank_orig}  = [];
    $self->{taggedbank}    = [];
    $self->{taggedbank_orig} = [];
    $self->{mathbank}      = [];
    $self->{math_masks}    = [];
}

sub mask {
    my ($self, $line) = @_;
    $line //= '';

    # Protect verbatim/raw/tagged/math – whichever appears first wins
    PROTECT: while (1) {
        my ($t, $r, $v, $m) = (length($line)+1) x 4;
        $t = $-[0] if $line =~ $regex{tagged};
        $r = $-[0] if $line =~ $regex{raw};
        $v = $-[0] if $line =~ $regex{fontMono};
        $m = $-[0] if $line =~ $regex{math};

        if ($t <= $r && $t <= $v && $t <= $m && $t < length($line)+1) {
            $line =~ $regex{tagged};
            my $orig = $&;
            my $txt = $1;
            $txt = doProtect($TARGET, $txt);
            my $i = scalar @{ $self->{taggedbank} };
            push @{ $self->{taggedbank} }, $txt;
            push @{ $self->{taggedbank_orig} }, $orig;
            (my $mask = $self->{taggedmask}) =~ s/NNN/$i/;
            $line =~ s/$regex{tagged}/$mask/;
        }
        elsif ($r <= $t && $r <= $v && $r <= $m && $r < length($line)+1) {
            $line =~ $regex{raw};
            my $orig = $&;
            my $txt = doEscape($TARGET, $1);
            my $i = scalar @{ $self->{rawbank} };
            push @{ $self->{rawbank} }, $txt;
            push @{ $self->{rawbank_orig} }, $orig;
            (my $mask = $self->{rawmask}) =~ s/NNN/$i/;
            $line =~ s/$regex{raw}/$mask/;
        }
        elsif ($v <= $t && $v <= $r && $v <= $m && $v < length($line)+1) {
            $line =~ $regex{fontMono};
            my $orig = $&;
            my $txt = doEscape($TARGET, $1);
            my $i = scalar @{ $self->{monobank} };
            push @{ $self->{monobank} }, $txt;
            push @{ $self->{monobank_orig} }, $orig;
            (my $mask = $self->{monomask}) =~ s/NNN/$i/;
            $line =~ s/$regex{fontMono}/$mask/;
        }
        elsif ($m <= $t && $m <= $r && $m <= $v && $m < length($line)+1) {
            $line =~ $regex{math};
            my $txt = doEscape($TARGET, $1);
            my $i = scalar @{ $self->{mathbank} };
            push @{ $self->{mathbank} }, $txt;
            (my $mask = $self->{mathmask}) =~ s/NNN/$i/;
            push @{ $self->{math_masks} }, $mask;
            $line =~ s/$regex{math}/$mask/;
        }
        else { last PROTECT }
    }

    # Protect macros
    while ($line =~ $regex{macros}) {
        my $txt = $&;
        my $i   = scalar @{ $self->{macrobank} };
        push @{ $self->{macrobank} }, $txt;
        (my $mask = $self->{macromask}) =~ s/NNN/$i/;
        $line =~ s/\Q$txt\E/$mask/;
    }

    # Protect %%toc
    if ($line =~ $regex{toc}) {
        $line =~ s/$regex{toc}/$self->{tocmask}/g;
        $AUTOTOC = 0;
    }

    # Protect URLs and emails
    while ($line =~ $regex{linkmark} || $line =~ $regex{link}) {
        my ($link, $label, $link_re);
        my $ml = $line =~ $regex{link}     ? pos() // $-[0] : undef;
        my $mn = $line =~ $regex{linkmark} ? pos() // $-[0] : undef;

        if (defined $ml && defined $mn) {
            if ($mn <= $ml) {
                $line =~ $regex{linkmark};
                $link    = fix_relative_path($+{link} // '');
                $label   = $+{label} // '';
                $label   =~ s/\s+$//;
                $link_re = $regex{linkmark};
            }
            else {
                $line =~ $regex{link};
                $link    = $&;
                $label   = '';
                $link_re = $regex{link};
            }
        }
        elsif (defined $mn) {
            $line =~ $regex{linkmark};
            $link    = fix_relative_path($+{link} // '');
            $label   = $+{label} // '';
            $label   =~ s/\s+$//;
            $link_re = $regex{linkmark};
        }
        else {
            $line =~ $regex{link};
            $link    = $&;
            $label   = '';
            $link_re = $regex{link};
        }

        my $i = scalar @{ $self->{linkbank} };
        push @{ $self->{linkbank} }, [$label, $link];
        (my $mask = $self->{linkmask}) =~ s/NNN/$i/;
        $line =~ s/$link_re/$mask/;
    }

    return $line;
}

sub undo {
    my ($self, $line) = @_;

    # Links
    while ($line =~ /$self->{linkmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my ($label, $url) = @{ $self->{linkbank}[$i] };
        my $tagged = get_tagged_link($label, $url);
        $line = substr($line, 0, $start) . $tagged . substr($line, $end);
    }

    # Macros
    while ($line =~ /$self->{macromaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $macro = $self->{macroman}->expand($self->{macrobank}[$i]);
        $line = substr($line, 0, $start) . $macro . substr($line, $end);
    }

    # Verbatim (mono)
    while ($line =~ /$self->{monomaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $txt   = ($TAGS{fontMonoOpen} // '') . $self->{monobank}[$i]
                  . ($TAGS{fontMonoClose} // '');
        $line = substr($line, 0, $start) . $txt . substr($line, $end);
    }

    # Raw
    while ($line =~ /$self->{rawmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        $line = substr($line, 0, $start) . $self->{rawbank}[$i] . substr($line, $end);
    }

    # Tagged
    while ($line =~ /$self->{taggedmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        $line = substr($line, 0, $start) . $self->{taggedbank}[$i] . substr($line, $end);
    }

    # Math (just restore as-is for non-special targets)
    while ($line =~ /$self->{mathmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        $line = substr($line, 0, $start) . $self->{mathbank}[$i] . substr($line, $end);
    }

    return $line;
}

# undo_title: restore masks to ORIGINAL markup (for use in title text)
# Raw/tagged/mono marks are kept as literal markup, not converted to HTML.
sub undo_title {
    my ($self, $line) = @_;

    # Restore raw masks as literal ""content"" with HTML-escaped content
    while ($line =~ /$self->{rawmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $literal = '""' . $self->{rawbank}[$i] . '""';
        $line = substr($line, 0, $start) . $literal . substr($line, $end);
    }

    # Restore tagged masks as literal ''content''
    while ($line =~ /$self->{taggedmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $literal = "''" . $self->{taggedbank}[$i] . "''";
        $line = substr($line, 0, $start) . $literal . substr($line, $end);
    }

    # Restore mono masks as literal ``content``
    while ($line =~ /$self->{monomaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $literal = '``' . $self->{monobank}[$i] . '``';
        $line = substr($line, 0, $start) . $literal . substr($line, $end);
    }

    # Links and macros are still expanded normally
    while ($line =~ /$self->{linkmaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my ($label, $url) = @{ $self->{linkbank}[$i] };
        my $tagged = get_tagged_link($label, $url);
        $line = substr($line, 0, $start) . $tagged . substr($line, $end);
    }

    while ($line =~ /$self->{macromaskre}/) {
        my $i     = $1;
        my $start = $-[0];
        my $end   = $+[0];
        my $macro = $self->{macroman}->expand($self->{macrobank}[$i]);
        $line = substr($line, 0, $start) . $macro . substr($line, $end);
    }

    return $line;
}

# ===========================================================================
# TitleMaster – heading numbering & TOC
# ===========================================================================

package Text::Txt2tags::TitleMaster;
# (no globals needed)

sub new {
    my ($class) = @_;
    return bless {
        count        => ['', 0, 0, 0, 0, 0],
        toc          => [],
        level        => 0,
        kind         => '',
        txt          => '',
        label        => '',
        tag          => '',
        tag_hold     => [],
        last_level   => 0,
        count_id     => '',
        anchor_count => 0,
        anchor_prefix=> 'toc',
    }, $class;
}

sub _get_label {
    my ($self) = @_;
    if ($self->{label}) {
        return $self->{label};
    }
    $self->{anchor_count}++;
    return sprintf('%s%03d', $self->{anchor_prefix}, $self->{anchor_count});
}

sub add {
    my ($self, $level, $kind, $txt, $label) = @_;
    $self->{level} = $level;
    $self->{kind}  = $kind;    # 'title' or 'numtitle'
    $self->{txt}   = $txt;
    $self->{label} = $label // '';

    # Increment counter for numbered titles
    if ($kind eq 'numtitle') {
        $self->{count}[$level]++;
        $self->{count}[$_] = 0 for ($level+1 .. 5);
        $self->{count_id}  = join('.', @{ $self->{count} }[1..$level]);
    }
    else {
        $self->{count_id} = '';
    }

    my $lbl = $self->_get_label;
    $self->{last_count_id} = ($kind eq 'numtitle') ? $self->{count_id} : '';

    # Build TOC entry
    my $indent = '  ' x ($level - 1);
    my $entry;
    if ($kind eq 'numtitle') {
        $entry = sprintf('%s- %s %s', $indent, $self->{count_id}, $txt);
    }
    else {
        $entry = sprintf('%s- %s', $indent, $txt);
    }
    push @{ $self->{toc} }, $entry;

    return $lbl;
}

sub last_count_id { return $_[0]->{last_count_id} // '' }

sub close {
    my ($self) = @_;
    $self->{tag_hold} = [];
}

# ===========================================================================
# BlockMaster – manage open/close block state (verb, quote, list…)
# ===========================================================================

package Text::Txt2tags::BlockMaster;
our (%TAGS, %rules);
BEGIN {
    *TAGS  = \%Text::Txt2tags::State::TAGS;
    *rules = \%Text::Txt2tags::State::rules;
}

sub new {
    my ($class) = @_;
    return bless {
        block_stack  => [],
        prop_stack   => [],   # per-block property dicts (like Python's PRP stack)
        hold         => [],
        exclusive    => [qw(verb raw tagged comment)],
        last         => '',
        _last_raw    => 0,
    }, $class;
}

sub block {
    my ($self) = @_;
    return $self->{block_stack}[-1] // '';
}

sub depth {
    my ($self) = @_;
    return scalar @{ $self->{block_stack} };
}

sub prop {
    my ($self, $name) = @_;
    return $self->{prop_stack}[-1]{$name} if @{ $self->{prop_stack} };
    return undef;
}

sub set_prop {
    my ($self, $name, $val) = @_;
    $self->{prop_stack}[-1]{$name} = $val if @{ $self->{prop_stack} };
}

# Map internal block names → TAGS key prefix
# e.g. 'verb' → 'blockVerb', 'quote' → 'blockQuote', 'para' → 'paragraph', ...
my %BLOCK_TAG_PREFIX = (
    verb    => 'blockVerb',
    raw     => 'blockRaw',
    tagged  => 'blockTagged',
    comment => 'blockComment',
    quote   => 'blockQuote',
    para    => 'paragraph',
    list    => 'list',
    numlist => 'numlist',
    deflist => 'deflist',
    table   => 'table',
);

sub _tag_prefix { $BLOCK_TAG_PREFIX{$_[1]} // $_[1] }

sub blockin {
    my ($self, $blockname) = @_;
    push @{ $self->{block_stack} }, $blockname;
    push @{ $self->{prop_stack} }, {};   # fresh props for this block
    $self->{hold} = [];
    my @out;

    my $pfx      = $self->_tag_prefix($blockname);
    my $tag_open = $TAGS{$pfx . 'Open'} // '';
    push @out, $tag_open if $tag_open;

    return \@out;
}

sub blockout {
    my ($self, $flag_isempty) = @_;
    $flag_isempty //= 0;
    my $blockname = pop @{ $self->{block_stack} } // '';
    pop @{ $self->{prop_stack} };        # discard this block's props
    my @out;

    return \@out if $flag_isempty;

    my $pfx = $self->_tag_prefix($blockname);

    # Flush held lines
    for my $line (@{ $self->{hold} }) {
        my $tag = $TAGS{$pfx . 'Line'} // '';
        if ($tag) {
            $line = $tag . $line;
        }
        # indentverbblock: add 2-space prefix to verbatim lines
        if ($blockname eq 'verb' && $rules{indentverbblock}) {
            $line = '  ' . $line;
        }
        push @out, $line;
    }
    $self->{hold} = [];

    my $tag_close = $TAGS{$pfx . 'Close'} // '';
    push @out, $tag_close if $tag_close;

    # Only update last if this block produced output (matching Python v2 behavior)
    $self->{last} = $blockname if @out;
    return \@out;
}

sub last {
    my ($self, $val) = @_;
    $self->{last} = $val if defined $val;
    return $self->{last};
}

sub holdadd {
    my ($self, $line) = @_;
    push @{ $self->{hold} }, $line;
}

sub holdaddfinal {
    my ($self, @lines) = @_;
    push @{ $self->{hold} }, @lines;
}

sub holdget {
    my ($self) = @_;
    return $self->{hold};
}

sub holdflush {
    my ($self) = @_;
    my @data = @{ $self->{hold} };
    $self->{hold} = [];
    return \@data;
}

# ===========================================================================
# TableMaster – build tagged table rows/cells
# ===========================================================================

package Text::Txt2tags::TableMaster;
our (%TAGS, %rules);
BEGIN {
    *TAGS  = \%Text::Txt2tags::State::TAGS;
    *rules = \%Text::Txt2tags::State::rules;
}

sub new {
    my ($class) = @_;
    return bless {
        rows        => [],
        border      => 0,
        align       => '',
        n_table     => 0,
    }, $class;
}

sub _parse_cell {
    my ($self, $cell, $is_title, $cell_proc, $colspan, $colindex, $colalign, $is_border_ctx) = @_;
    $colspan      //= 1;
    $colalign     //= [];
    $is_border_ctx //= 0;

    # Detect alignment BEFORE stripping (based on leading/trailing spaces)
    # Python splits by " | " so cells have 1 extra space per alignment level:
    # 1 leading AND 1 trailing → Center
    # 1 leading only → Right
    # Otherwise → no special alignment (default left)
    # Only detect alignment if cell has non-space content (matches Python: if cell.strip())
    my $align = '';
    my $cell_stripped = $cell;
    $cell_stripped =~ s/^\s+|\s+$//g;
    if ($cell_stripped ne '') {
        if ($cell =~ /^ / && $cell =~ / $/) { $align = 'Center' }
        elsif ($cell =~ /^ /)               { $align = 'Right'  }
    }
    # Default alignment is Left
    my $cell_align = $align || 'Left';

    $cell =~ s/^\s+|\s+$//g if $rules{tablecellstrip};

    # Python: title rows fall back to normal cell tags if title-specific ones aren't defined
    my $open_tag  = $is_title
        ? ($TAGS{tableTitleCellOpen}  || $TAGS{tableCellOpen}  // '')
        : ($TAGS{tableCellOpen}  // '');
    my $close_tag = $is_title
        ? ($TAGS{tableTitleCellClose} || $TAGS{tableCellClose} // '')
        : ($TAGS{tableCellClose} // '');

    if ($align && $rules{tablecellaligntype} && $rules{tablecellaligntype} eq 'cell' && $cell =~ /\S/) {
        my $align_tag = $TAGS{"_tableCellAlign$align"} // '';
        $open_tag =~ s/~A~/$align_tag/;
    }
    if ($colspan > 1 && $TAGS{_tableCellColSpan}) {
        my $span_tag = $TAGS{_tableCellColSpan};
        $span_tag =~ s/\\a/$colspan/g;
        $open_tag =~ s/~S~/$span_tag/;
    }
    $open_tag =~ s/~[AS]~//g;  # remove unused placeholders

    # Apply text processing (escape, inline tags, unmask) FIRST
    $cell = $cell_proc->($cell) if $cell_proc;

    # Bold wrapping for title rows AFTER cell_proc (matching Python order)
    if ($is_title && $rules{tabletitlerowinbold}) {
        my $bo = $TAGS{fontBoldOpen}  // '';
        my $bc = $TAGS{fontBoldClose} // '';
        $cell = "$bo$cell$bc";
    }

    # Multicol support: wrap cell when alignment differs from column default,
    # or when colspan > 1 (Python: tablecellmulticol rule)
    if ($rules{tablecellmulticol} && $TAGS{_tableCellMulticolOpen}) {
        my $calignsep = $TAGS{tableColAlignSep} // '';
        my $col_default = ($colindex < scalar @$colalign) ? $colalign->[$colindex] : 'Left';
        my $need_multicol = ($colspan > 1) || ($cell_align ne $col_default);
        if ($need_multicol) {
            my $span_n = $colspan;
            my $mc_open = $TAGS{_tableCellMulticolOpen};
            # Replace \a with span count
            $mc_open =~ s/\\a/$span_n/g;
            # Replace ~C~ with cell alignment letter
            my $align_letter = $TAGS{"_tableColAlign$cell_align"} // 'l';
            $mc_open =~ s/~C~/$align_letter/g;
            # For non-border tables: remove calignsep from multicol tag
            if ($calignsep && !$is_border_ctx) {
                $mc_open =~ s/\Q$calignsep\E//g;
            }
            $open_tag  = $mc_open;
            $close_tag = $TAGS{_tableCellMulticolClose} // '';
        }
    }

    return ($open_tag, $cell, $close_tag);
}

sub parse_row_props {
    my ($self, $line) = @_;
    # Returns { cellalign, cellspan, colalign } without processing cells
    $line =~ s/^ +//;
    if ($line =~ / \|+ *$/) {
        $line .= ' ';
    } else {
        $line .= ' | ';
    }
    $line =~ s/^ *\|[|_\/]? //;
    $line =~ s/ (\|+)\| /\x07$1 | /g;
    my @raw_cells = split(/ \| /, $line, -1);
    pop @raw_cells;
    my (@cells, @cellspan);
    for my $cell (@raw_cells) {
        my $span = 1;
        if ($cell =~ /\x07(\|+)$/) {
            $span = 1 + length($1);
            $cell =~ s/\x07\|+$//;
        }
        push @cells, $cell;
        push @cellspan, $span;
    }
    my @cellalign;
    for my $cell (@cells) {
        my $align = 'Left';
        my $stripped = $cell;
        $stripped =~ s/^\s+|\s+$//g;
        if ($stripped ne '') {
            if ($cell =~ /^ / && $cell =~ / $/) { $align = 'Center' }
            elsif ($cell =~ /^ /)               { $align = 'Right'  }
        }
        push @cellalign, $align;
    }
    my @colalign;
    for my $i (0..$#cellalign) {
        push @colalign, ($cellalign[$i]) x $cellspan[$i];
    }
    return { cellalign => \@cellalign, cellspan => \@cellspan, colalign => \@colalign };
}

sub parse_row {
    my ($self, $line, $cell_proc, $context) = @_;
    $context //= {};
    my $table_colalign  = $context->{colalign}          // [];
    my $table_is_border = $context->{is_border}         // 0;
    my $row_open_override = $context->{row_open_override};  # undef = use TAGS

    my $is_title  = 0;
    my $is_border = 0;

    # Match Python: lstrip, then detect table marks by position
    $line =~ s/^ +//;

    # Detect title mark: line[1] == '|' means || prefix
    if (length($line) > 1 && substr($line, 1, 1) eq '|') {
        $is_title = 1;
    }

    # Detect border mark and normalize EOL
    # Python: m = re.search(r" (\|+) *$", line)
    if ($line =~ / \|+ *$/) {
        $line .= ' ';       # border detected: add trailing space
        $is_border = 1;
    } else {
        $line .= ' | ';     # no border: add fake " | " terminator
    }

    # Delete table mark: Python regex is ^ *\|([|_/])? (note: trailing space required)
    # This removes the leading | (or ||, |_, |/) plus one space
    $line =~ s/^ *\|[|_\/]? //;

    # Detect colspan: Python: re.sub(r" (\|+)\| ", "\a\\1 | ", line)
    # \a = chr(7) = \x07. No leading space in replacement — matches Python exactly.
    $line =~ s/ (\|+)\| /\x07$1 | /g;

    # Split cells by " | " (space-pipe-space), drop the fake last element
    # This naturally strips single-space padding, matching Python's behavior
    my @raw_cells = split(/ \| /, $line, -1);
    pop @raw_cells;  # remove fake last element

    # Process colspan using \x07 marker (Python's \a marker approach)
    my @cells;
    for my $cell (@raw_cells) {
        my $span = 1;
        if ($cell =~ /\x07(\|+)$/) {
            $span = 1 + length($1);
            $cell =~ s/\x07\|+$//;
        }
        push @cells, [$cell, $span];
    }
    # Python's two-pass (join+split on SEPARATOR) produces [""] for empty rows
    # (e.g. "| |"), giving one empty cell. Replicate that behaviour here.
    push @cells, ['', 1] unless @cells;

    # Choose row open/close based on whether this is a title row
    my ($row_open, $row_close, $cell_sep);
    if ($is_title && $TAGS{tableTitleRowOpen}) {
        $row_open  = $TAGS{tableTitleRowOpen}  // '';
        $row_close = $TAGS{tableTitleRowClose} // '';
        $cell_sep  = $TAGS{tableTitleCellSep}  // '';
    } else {
        $row_open  = $TAGS{tableRowOpen}  // '';
        $row_close = $TAGS{tableRowClose} // '';
        $cell_sep  = $TAGS{tableCellSep}  // '';
    }

    # Apply row_open override from context (e.g. tex non-border suppresses \hline)
    $row_open = $row_open_override if defined $row_open_override;

    # Python: breaktablelineopen adds \n after rowopen
    $row_open .= "\n" if $rules{breaktablelineopen};

    # Python always joins all cells on one line (with sep, which may be empty).
    # The row_open/row_close wrap the entire joined string.
    # breaktablecell adds \n after each cell's close tag.
    my @cell_strings;
    my $colindex = 0;
    for my $cell_info (@cells) {
        my ($cell, $colspan) = @$cell_info;
        $cell //= '';
        my ($co, $ctxt, $cc) = $self->_parse_cell(
            $cell, $is_title, $cell_proc, $colspan,
            $colindex, $table_colalign, $table_is_border
        );
        $cc .= "\n" if $rules{breaktablecell};
        push @cell_strings, "$co$ctxt$cc";
        $colindex += $colspan;
    }
    my $row = $row_open . join($cell_sep, @cell_strings) . $row_close;
    # Split on embedded newlines to produce multi-line output
    return [split /\n/, $row, -1];
}

# ===========================================================================
# Exports
# ===========================================================================
package Text::Txt2tags::Processing;

our @EXPORT_OK = qw();   # classes are used by full name

1;
__END__

=head1 NAME

Text::Txt2tags::Processing - Core markup processing classes

=head1 DESCRIPTION

Port of C<txt2tags3_mod/processing.py> to Perl 5.

Provides:

=over 4

=item C<Text::Txt2tags::MacroMaster> – expand C<%%macroname> macros.

=item C<Text::Txt2tags::MaskMaster> – protect inline structures during parsing.

=item C<Text::Txt2tags::TitleMaster> – heading numbering and TOC accumulation.

=item C<Text::Txt2tags::BlockMaster> – block state machine (verb/quote/list/…).

=item C<Text::Txt2tags::TableMaster> – table row/cell tagging.

=back

=cut

END_OF_MODULE_SOURCE
    $_bundled{'Text/Txt2tags/Output.pm'} = <<'END_OF_MODULE_SOURCE';
package Text::Txt2tags::Output;

# txt2tags - output helpers: escaping, tags, TOC, headers/footers
# Port of txt2tags3_mod/output.py to Perl 5

use strict;
use warnings;
use Exporter 'import';
use POSIX qw();

our $VERSION = '3.9.0';

use Text::Txt2tags::Constants qw(
    $MY_NAME $MY_VERSION $MY_URL %ESCAPES %TARGET_TYPES %TARGET_NAMES
    $ESCCHAR $SEPARATOR %AA DFT_TEXT_WIDTH $STDOUT $MODULEOUT
);
use Text::Txt2tags::State qw(
    $AUTOTOC %CONF %TAGS %rules %regex $QUIET $DEBUG $VERBOSE
);
use Text::Txt2tags::Utils qw(Error Message Debug Readfile Savefile dotted_spaces);

# ---------------------------------------------------------------------------
# Escaping helpers
# ---------------------------------------------------------------------------

sub get_escapes {
    my ($target) = @_;
    $target = 'tex' if $target eq 'texs';
    return $ESCAPES{$target} // [];
}

sub doProtect {
    my ($target, $txt) = @_;
    for my $triple (@{ get_escapes($target) }) {
        my ($before, $protected, $after) = @$triple;
        $txt =~ s/\Q$before\E/$protected/g;
    }
    return $txt;
}

sub doEscape {
    my ($target, $txt) = @_;
    my $tmpmask = 'vvvvThisEscapingSuxvvvv';

    if ($rules{escapexmlchars}) {
        $txt =~ s/&/&amp;/g;
        $txt =~ s/</&lt;/g;
        $txt =~ s/>/&gt;/g;
    }

    if ($target eq 'sgml') {
        $txt =~ s/\xff/&yuml;/g;
    }
    elsif ($target eq 'pm6') {
        $txt =~ s/</\<\\#60\>/g;
    }
    elsif ($target eq 'mgp') {
        $txt =~ s/^%/ %/mg;
    }
    elsif ($target eq 'man') {
        $txt =~ s/^([.'])/\\&$1/mg;
        $txt =~ s/\Q$ESCCHAR\E/${ESCCHAR}e/g;
    }
    elsif ($target eq 'lout') {
        $txt =~ s/\Q$ESCCHAR\E/$tmpmask/g;
        $txt =~ s/"/"${ESCCHAR}""/g;
        $txt =~ s/([|&{}\@#^~])/"$1"/g;
        $txt =~ s/$tmpmask/"${ESCCHAR}${ESCCHAR}"/g;
    }
    elsif ($target =~ /^tex/) {
        $txt =~ s/\Q$ESCCHAR\E/$tmpmask/g;
        $txt =~ s/([#\$&%{}])/${ESCCHAR}$1/g;
        $txt =~ s/([~^])/${ESCCHAR}$1\{\}/g;
        $txt =~ s/([<|>])/\$$1\$/g;
        $txt =~ s/$tmpmask/maskEscapeChar('$\\backslash$')/ge;
    }
    elsif ($target eq 'rtf') {
        $txt =~ s/\Q$ESCCHAR\E/$ESCCHAR$ESCCHAR/g;
        $txt =~ s/([{}])/${ESCCHAR}$1/g;
    }
    return $txt;
}

sub doFinalEscape {
    my ($target, $txt) = @_;
    for my $triple (@{ get_escapes($target) }) {
        my ($before, $protected, $after) = @$triple;
        $txt =~ s/\Q$before\E/$after/g;
        $txt =~ s/\Q$protected\E/$before/g;
    }
    return $txt;
}

sub EscapeCharHandler {
    my ($action, $data) = @_;
    return $data unless $data =~ /\S/;
    if ($action eq 'mask') {
        $data =~ s/\\/$ESCCHAR/g;
    }
    elsif ($action eq 'unmask') {
        $data =~ s/\Q$ESCCHAR\E/\\/g;
    }
    else {
        Error("EscapeCharHandler: Invalid action '$action'");
    }
    return $data;
}

sub maskEscapeChar {
    my ($data) = @_;
    if (ref $data eq 'ARRAY') {
        return [ map { EscapeCharHandler('mask', $_) } @$data ];
    }
    return EscapeCharHandler('mask', $data);
}

sub unmaskEscapeChar {
    my ($data) = @_;
    if (ref $data eq 'ARRAY') {
        return [ map { EscapeCharHandler('unmask', $_) } @$data ];
    }
    return EscapeCharHandler('unmask', $data);
}

# ---------------------------------------------------------------------------
# Line-break helpers
# ---------------------------------------------------------------------------

sub addLineBreaks {
    my ($list) = @_;
    my @ret;
    for my $line (@$list) {
        $line =~ s/\n/\n/g;   # embedded \n stays as-is
        push @ret, "$line\n";
    }
    return \@ret;
}

sub expandLineBreaks {
    my ($list) = @_;
    my @ret;
    for my $line (@$list) {
        if (!defined $line || $line eq '') {
            push @ret, '';   # preserve blank lines (split discards them)
        } else {
            push @ret, split /\n/, $line, -1;
        }
    }
    return \@ret;
}

# ---------------------------------------------------------------------------
# Filter compilation
# ---------------------------------------------------------------------------

# Build a replacement closure from a template that may contain \1..\9 or $1..$9
# backreferences.  The closure is called within s/$rgx/$fn->()/ge so that
# $1,$2,... from the outer match are still alive when the closure runs.
sub _make_repl_closure {
    my ($template) = @_;
    # Normalise Python-style \1 → $1
    (my $tmpl = $template) =~ s/\\([1-9])/\$$1/g;
    return sub {
        # Snapshot the outer-match capture groups before any inner regex clobbers them
        my @c = ($1,$2,$3,$4,$5,$6,$7,$8,$9);
        (my $r = $tmpl) =~ s/\$([1-9])/defined $c[$1-1] ? $c[$1-1] : ''/ge;
        $r
    };
}

sub compile_filters {
    my ($filters, $errmsg) = @_;
    $errmsg //= 'Filter';
    return [] unless $filters && @$filters;
    my @compiled;
    for my $pair (@$filters) {
        my ($patt, $repl) = @$pair;
        # Perl 5.26+ rejects unescaped { that are not valid quantifiers
        # ({n}, {n,}, {n,m}).  Python's re allows them, so auto-escape here.
        $patt =~ s/\{(?!\d+,?\d*\})/\\{/g;
        my $rgx = eval { qr/$patt/m };
        Error("$errmsg: '$patt': $@") if $@;
        push @compiled, [$rgx, _make_repl_closure($repl)];
    }
    return \@compiled;
}

# ---------------------------------------------------------------------------
# Tag helpers
# ---------------------------------------------------------------------------

sub enclose_me {
    my ($tagname, $txt) = @_;
    return ($TAGS{$tagname . 'Open'} // '')
         . $txt
         . ($TAGS{$tagname . 'Close'} // '');
}

sub get_tagged_link {
    my ($label, $url) = @_;

    my $target = $CONF{target} // '';

    my $is_email = ($url =~ /^[\w.+-]+\@[\w.-]+\.[A-Za-z]{2,4}/);
    my $is_img   = ($url =~ /\.(png|jpe?g|gif|eps|bmp|svg)$/i);

    my ($open_tag, $close_tag);

    if ($label) {
        if ($is_email) {
            $open_tag  = $TAGS{emailMark} // '';
            $close_tag = '';
        }
        else {
            $open_tag  = $TAGS{urlMark} // '';
            $close_tag = '';
        }
    }
    else {
        if ($is_email) {
            $open_tag  = $TAGS{email} // '';
            $close_tag = '';
        }
        else {
            $open_tag  = $TAGS{url} // '';
            $close_tag = '';
        }
    }

    # Add protocol to bare www.*/ftp.* URLs (guessed URLs)
    my $orig_url = $url;
    if (!$is_email && $url =~ /^(?:www[23]?|ftp)\./i) {
        my $proto = ($url =~ /^ftp\./i) ? 'ftp://' : 'http://';
        $url = $proto . $url;
    }

    # Escape specials in URL (Python: if not linkable or escapeurl)
    # doEscape handles & → &amp; for escapexmlchars targets (HTML etc.)
    if (!$rules{linkable} || $rules{escapeurl}) {
        $url = doEscape($target, $url);
    }

    # Escape specials in label text (Python always does this)
    $label = doEscape($target, $label) if $label;

    # Use the (already-escaped) url directly for href
    my $url_esc = $url;

    # Display: label if given, else original URL text (no added proto)
    my $display;
    if ($label) {
        # Check if label is an image [img.ext] → expand to <IMG> tag
        if ($label =~ /^\[([A-Za-z0-9_,.+%\$#\@!?+~\/-]+\.(?:png|jpe?g|gif|eps|bmp|svg))\]$/i) {
            my $img_src = $1;
            my $img_tag = $TAGS{img} // '';
            if ($img_tag) {
                my $align_tag = $rules{imgalignable} ? ($TAGS{_imgAlignCenter} // '') : '';
                $img_tag =~ s/~A~/$align_tag/g;
                my $first2 = 1;
                $img_tag =~ s/\\a/$first2 ? do { $first2=0; $img_src } : $img_src/ge;
                $display = $img_tag;
            } else {
                $display = $label;
            }
        } else {
            $display = $label;  # already escaped by doEscape above
        }
    } else {
        # No label: display the original URL (without added protocol)
        # Escape it the same way as the URL
        my $disp_url = $orig_url;
        if (!$rules{linkable} || $rules{escapeurl}) {
            $disp_url = doEscape($target, $disp_url);
        }
        $display = $disp_url;
    }

    # Substitution order: labelbeforelink OR non-linkable target → label first, URL second
    my ($first_val, $second_val);
    if ($label && ($rules{labelbeforelink} || !$rules{linkable})) {
        $first_val  = $display;
        $second_val = $url_esc;
    } else {
        $first_val  = $url_esc;
        $second_val = $display;
    }
    my $result = $open_tag;
    my $first  = 1;
    $result =~ s/\\a/$first ? do { $first = 0; $first_val } : $second_val/ge;

    return $result;
}

sub parse_deflist_term {
    my ($line) = @_;
    if ($line =~ /^( *): (.*)$/) {
        return ($1, $2);
    }
    return ('', $line);
}

sub get_image_align {
    my ($img_tag) = @_;
    # Look for leading/trailing spaces around [image]
    if ($img_tag =~ /^\s+\[/) { return 'right'  }
    if ($img_tag =~ /\]\s+$/) { return 'left'   }
    return 'center';
}

sub get_encoding_string {
    my ($encoding, $target) = @_;
    return '' unless $encoding;
    my $enc_lc = lc $encoding;
    if ($target =~ /^x?html/) {
        return qq{<meta http-equiv="Content-Type" content="text/html; charset=$encoding">};
    }
    elsif ($target eq 'tex' || $target eq 'texs') {
        my %tex_enc = (
            'utf-8'       => 'utf8',
            'iso-8859-1'  => 'latin1',
            'iso-8859-2'  => 'latin2',
        );
        my $tex = $tex_enc{$enc_lc} or return '';
        return "\\usepackage[$tex]{inputenc}";
    }
    elsif ($target eq 'sgml') {
        return qq{<!doctype html public "-//W3C//DTD HTML 4.0 Transitional//EN"\n"http://www.w3.org/TR/REC-html40/loose.dtd">};
    }
    return '';
}

# ---------------------------------------------------------------------------
# Comment line
# ---------------------------------------------------------------------------

sub doCommentLine {
    my ($txt) = @_;
    $txt = maskEscapeChar($txt);
    my $ctag = $TAGS{comment} // '';
    if ($ctag =~ /--/ && $txt =~ /--/) {
        $txt =~ s/-(?=-)/-\\/g;
    }
    return '' unless $ctag;
    $txt =~ s/\a/$txt/;    # \a placeholder
    (my $out = $ctag) =~ s/\\a/$txt/;
    return $out;
}

# ---------------------------------------------------------------------------
# post_voodoo
# ---------------------------------------------------------------------------

sub post_voodoo {
    my ($lines, $config) = @_;
    my $loser1 = 'No, no. Your PostVoodoo regex is wrong.';
    my $loser2 = 'Dear PostVoodoo apprentice: regex right but replacement wrong';
    my $subject = join "\n", @$lines;
    my $spells  = compile_filters($config->{postvoodoo}, $loser1);
    for my $pair (@$spells) {
        my ($rgx, $repl_fn) = @$pair;
        eval { $subject =~ s/$rgx/$repl_fn->()/ge };
        Error($loser2) if $@;
    }
    return [ split /\n/, $subject, -1 ];
}

# ---------------------------------------------------------------------------
# finish_him – write output
# ---------------------------------------------------------------------------

sub finish_him {
    my ($outlist, $config) = @_;
    my $outfile = $config->{outfile};
    if ($DEBUG) {
        my $lim2 = $#$outlist < 15 ? $#$outlist : 15;
        print STDERR "DEBUG finish_him ENTRY: outlist has ", scalar(@$outlist), " lines\n";
        for my $i (0..$lim2) {
            print STDERR "  entry[$i]: <<$outlist->[$i]>>\n";
        }
    }
    $outlist = unmaskEscapeChar($outlist);
    $outlist = expandLineBreaks($outlist);

    # Apply postproc filters
    if ($config->{postproc} && @{ $config->{postproc} }) {
        my $filters = compile_filters($config->{postproc}, 'Invalid PostProc filter regex');
        my @post;
        for my $line (@$outlist) {
            for my $pair (@$filters) {
                my ($rgx, $repl_fn) = @$pair;
                eval { $line =~ s/$rgx/$repl_fn->()/ge };
                Error('Invalid PostProc filter replacement') if $@;
            }
            push @post, $line;
        }
        $outlist = \@post;
    }

    if ($config->{postvoodoo} && @{ $config->{postvoodoo} }) {
        $outlist = post_voodoo($outlist, $config);
    }

    # Save to file_dict (global via State)
    if ($DEBUG) {
        my $lim = $#$outlist < 15 ? $#$outlist : 15;
        print STDERR "DEBUG finish_him: outlist has ", scalar(@$outlist), " lines\n";
        for my $i (0..$lim) {
            print STDERR "  [$i]: <<$outlist->[$i]>>\n";
        }
    }
    $Text::Txt2tags::State::file_dict{$outfile} = $outlist
        unless $config->{target} =~ /^csv/;

    if ($outfile eq $MODULEOUT) {
        my @all;
        push @all, $Text::Txt2tags::State::file_dict{$_}
            for keys %Text::Txt2tags::State::file_dict;
        return \@all;
    }
    elsif ($outfile eq $STDOUT) {
        my @all;
        push @all, @{ $Text::Txt2tags::State::file_dict{$_} // [] }
            for keys %Text::Txt2tags::State::file_dict;
        print "$_\n" for @all;
    }
    else {
        for my $wf (keys %Text::Txt2tags::State::file_dict) {
            Savefile($wf, addLineBreaks($Text::Txt2tags::State::file_dict{$wf}));
        }
        unless ($QUIET) {
            print "$MY_NAME wrote $_\n"
                for keys %Text::Txt2tags::State::file_dict;
        }
    }
    return;
}

# ---------------------------------------------------------------------------
# fix_relative_path
# ---------------------------------------------------------------------------

sub fix_relative_path {
    my ($path) = @_;
    return $path unless $CONF{'fix-path'};
    return $path if $path =~ /^https?:|^ftp:|^#/;
    return $path if $path =~ m{^/};
    return $path if $CONF{infile} =~ /^-/;
    return $path if ($CONF{outfile} // '') =~ /^-/;

    my $src_dir = $CONF{sourcefile} // '';
    if ($src_dir) {
        require File::Basename;
        $src_dir = File::Basename::dirname($src_dir);
    }
    require File::Spec;
    return File::Spec->rel2abs($path, $src_dir);
}

# ---------------------------------------------------------------------------
# fix_css_out_path
# ---------------------------------------------------------------------------

sub fix_css_out_path {
    my ($config) = @_;
    return [] unless $config->{style} && @{ $config->{style} };
    return $config->{style};
}

# ---------------------------------------------------------------------------
# beautify_me – indent/format output
# ---------------------------------------------------------------------------

sub beautify_me {
    my ($what, $tag, $config) = @_;
    my @ret;
    if ($rules{indentverbblock} && $what eq 'verb') {
        push @ret, '    ' . $_ for @$tag;
    }
    else {
        push @ret, @$tag;
    }
    return \@ret;
}

# ---------------------------------------------------------------------------
# TOC functions
# ---------------------------------------------------------------------------

sub toc_inside_body {
    my ($body, $toc, $config) = @_;
    return $body if $AUTOTOC;

    my $toc_mark = 'vvvTOCvvv';
    my @ret;
    for my $line (@$body) {
        if (index($line, $toc_mark) >= 0) {
            push @ret, @$toc if $config->{toc};
        }
        else {
            push @ret, $line;
        }
    }
    return \@ret;
}

sub toc_tagger {
    my ($toc, $config) = @_;
    my @ret;
    if ($config->{'toc-only'} || ($config->{toc} && !$TAGS{TOC})) {
        # convert the TOC list (t2t markup) to target format
        my %fakeconf = %$config;
        $fakeconf{headers}    = 0;
        $fakeconf{'toc-only'} = 0;
        $fakeconf{'mask-email'} = 0;
        $fakeconf{preproc}    = [];
        $fakeconf{postproc}   = [];
        $fakeconf{postvoodoo} = [];
        $fakeconf{'css-sugar'}= 0;
        $fakeconf{'fix-path'} = 0;
        require Text::Txt2tags::Converter;
        my ($body, undef) = Text::Txt2tags::Converter::convert($toc, \%fakeconf);
        @ret = @$body;
    }
    elsif ($config->{toc} && $TAGS{TOC}) {
        @ret = ($TAGS{TOC});
    }
    return \@ret;
}

sub toc_formatter {
    my ($toc, $config) = @_;
    return $toc if $config->{'toc-only'};
    return []   unless $config->{toc};

    my @ret = @$toc;
    unshift @ret, $TAGS{tocOpen}  if $TAGS{tocOpen};
    push    @ret, $TAGS{tocClose} if $TAGS{tocClose};

    if ($AUTOTOC) {
        if ($rules{autotocwithbars}) {
            my $para = ($TAGS{paragraphOpen} // '') . ($TAGS{paragraphClose} // '');
            my $bar  = $TAGS{bar1} // ('-' x DFT_TEXT_WIDTH);
            $bar =~ s/\a/'-' x DFT_TEXT_WIDTH/e if $bar =~ /\a/;
            my @tocbar = ($para, $bar, $para);
            @ret = (@tocbar, @ret, @tocbar);
        }
        push @ret, '' if $rules{blankendautotoc};
        unshift @ret, $TAGS{pageBreak} if $rules{autotocnewpagebefore};
        push    @ret, $TAGS{pageBreak} if $rules{autotocnewpageafter};
    }
    return \@ret;
}

